
const KEY = "anugraha_products_v2";
const ORDER_KEY = "anugraha_orders_v1";
let products = [];
let toastTimer;

const $ = id => document.getElementById(id);

function fromDefault(p){
  return {id:String(p.id),name:p.name,category:p.label||p.cat||"Vegetables",image:p.img||"",emoji:p.emoji||"🛒",
    variants:(p.sizes||[]).map(v=>({size:v.l,price:Number(v.p)||0,mrp:Number(v.mrp)||0,stock:50,offerPrice:0}))};
}
try {
  const stored=JSON.parse(localStorage.getItem(KEY));
  // Treat an empty catalogue as uninitialized and restore the bundled products.
  products=Array.isArray(stored) && stored.length ? stored : DEFAULT_PRODUCTS.map(fromDefault);
} catch(e) { products=DEFAULT_PRODUCTS.map(fromDefault); }
// Refresh bundled product photos for this catalogue update, including existing admin data.
const bundledImageOverrides = new Map([
  ["Amul Dark Chocolate","data:image/jpeg;base64,"],
  ["Magnum Chocolate Truffle","data:image/jpeg;base64,"],
  ["Ripe Bananas","data:image/jpeg;base64,"],
  ["Oreo Chocolate Sundae","data:image/jpeg;base64,"],
  ["Alphonso Mango Ice Cream","data:image/jpeg;base64,"],
  ["Soft Drink","data:image/jpeg;base64,"],
  ["Fresh Orange Juice","data:image/jpeg;base64,"],
  ["Rice","data:image/jpeg;base64,"],
  ["Bread","data:image/jpeg;base64,"],
  ["Milk","data:image/jpeg;base64,"]
]);
const defaultImageById = new Map(DEFAULT_PRODUCTS.map(d => [String(d.id), d.img]));
products.forEach(p => {
  const bundledImage = bundledImageOverrides.get(p.name);
  if (bundledImage) p.image = bundledImage;
  else if (!p.image || /^images\//.test(p.image)) p.image = defaultImageById.get(String(p.id)) || p.image || "";
});
localStorage.setItem(KEY,JSON.stringify(products));
let selectedImage = "";

const money = n => "₹" + Number(n).toLocaleString("en-IN");
const safe = s => String(s ?? "").replace(/[&<>"']/g, c =>
  ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])
);

function save() {
  try { localStorage.setItem(KEY, JSON.stringify(products)); } catch(e) { notify("Storage full. Choose a smaller image file."); return; }
  renderAll();
}

function notify(msg) {
  const t = $("toast");
  t.textContent = msg;
  t.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.classList.remove("show"), 2200);
}

// NAVIGATION
function go(page) {
  document.querySelectorAll(".page").forEach(p =>
    p.classList.toggle("active", p.id === page)
  );

  document.querySelectorAll(".nav").forEach(n =>
    n.classList.toggle("active", n.dataset.page === page)
  );

  $("crumb").textContent =
    page==="orders" ? "Live orders" : page.charAt(0).toUpperCase() + page.slice(1);
  if (page==="orders") renderOrders();

  $("sidebar").classList.remove("open");
  window.scrollTo({top:0,behavior:"smooth"});
}

document.querySelectorAll(".nav").forEach(n =>
  n.addEventListener("click", () => go(n.dataset.page))
);

$("menuBtn").onclick = () =>
  $("sidebar").classList.toggle("open");

// VARIANT FORM
function addVariant(v = {}) {
  const row = document.createElement("div");
  row.className = "variant-row";

  row.innerHTML = `
    <div><label>Size</label>
      <input class="v-size" placeholder="500g"
        value="${safe(v.size || "")}" required>
    </div>
    <div><label>Price ₹</label>
      <input class="v-price" type="number" min="0.01"
        step="0.01" placeholder="40"
        value="${v.price ?? ""}" required>
    </div>
    <div><label>MRP ₹</label>
      <input class="v-mrp" type="number" min="0"
        step="0.01" placeholder="50"
        value="${v.mrp || ""}">
    </div>
    <div><label>Stock</label>
      <input class="v-stock" type="number" min="0"
        step="1" placeholder="10"
        value="${v.stock ?? 0}" required>
    </div>
    <div><label>Offer ₹</label>
      <input class="v-offer" type="number" min="0"
        step="0.01" placeholder="Optional"
        value="${v.offerPrice || ""}">
    </div>
    <button type="button" class="remove-variant"
      title="Remove size">×</button>
  `;

  $("variants").appendChild(row);
}

$("addVariant").onclick = () => addVariant();

$("variants").addEventListener("click", e => {
  if (e.target.classList.contains("remove-variant")) {
    const rows = $("variants").querySelectorAll(".variant-row");
    if (rows.length === 1) {
      notify("At least one size is required.");
      return;
    }
    e.target.closest(".variant-row").remove();
  }
});

// IMAGE FILE UPLOAD — resize/compress so it fits browser storage more reliably.
$("imageFile").addEventListener("change", e => {
  const file=e.target.files && e.target.files[0]; if(!file) return;
  if(!file.type.startsWith("image/")){notify("Please choose an image file.");return;}
  const reader=new FileReader();
  reader.onload=()=>{
    const img=new Image();
    img.onload=()=>{
      const canvas=document.createElement("canvas"), max=700;
      const scale=Math.min(1,max/Math.max(img.width,img.height));
      canvas.width=Math.round(img.width*scale); canvas.height=Math.round(img.height*scale);
      canvas.getContext("2d").drawImage(img,0,0,canvas.width,canvas.height);
      selectedImage=canvas.toDataURL("image/jpeg",0.72);
      $("image").value="";
      $("imagePreview").innerHTML=`<img src="${selectedImage}" alt="Selected product image"><button type="button" id="clearImage">Remove image</button>`;
    };
    img.onerror=()=>notify("Could not read this image."); img.src=reader.result;
  };
  reader.readAsDataURL(file);
});
$("imagePreview").addEventListener("click",e=>{if(e.target.id==="clearImage"){selectedImage="";$("imageFile").value="";$("imagePreview").innerHTML="";}});
$("image").addEventListener("input",()=>{if($("image").value.trim()){selectedImage="";$("imageFile").value="";$("imagePreview").innerHTML="";}});

// RESET / ADD
function resetForm() {
  $("productForm").reset();
  $("editId").value = "";
  $("formTitle").textContent = "Add product";
  $("saveBtn").textContent = "Save product";
  $("variants").replaceChildren();
  selectedImage=""; $("imageFile").value=""; $("imagePreview").innerHTML="";
  addVariant();
}

function openAdd() {
  go("products");
  resetForm();
  $("formPanel").scrollIntoView({behavior:"smooth"});
  $("name").focus();
}

$("cancel").onclick = resetForm;

// SAVE PRODUCT
$("productForm").onsubmit = e => {
  e.preventDefault();

  const name = $("name").value.trim();
  const category = $("category").value.trim();
  const image = selectedImage || $("image").value.trim();

  if (image && !image.startsWith("data:image/")) {
    try {
      const u = new URL(image);
      if (!["http:", "https:"].includes(u.protocol))
        throw new Error();
    } catch {
      notify("Enter a valid image URL.");
      return;
    }
  }

  const rows = [...$("variants").querySelectorAll(".variant-row")];
  const variants = [];

  for (const row of rows) {
    const size = row.querySelector(".v-size").value.trim();
    const price = Number(row.querySelector(".v-price").value);
    const mrp = Number(row.querySelector(".v-mrp").value || 0);
    const stock = Number(row.querySelector(".v-stock").value);
    const offerPrice = Number(row.querySelector(".v-offer").value || 0);

    if (!size || !Number.isFinite(price) || price <= 0 ||
        !Number.isInteger(stock) || stock < 0 ||
        (mrp > 0 && mrp < price) ||
        (offerPrice > 0 && offerPrice >= price)) {
      notify("Check size, price, MRP, stock and offer.");
      return;
    }

    variants.push({size, price, mrp, stock, offerPrice});
  }

  const id = $("editId").value;

  if (id) {
    const p = products.find(p => String(p.id) === id);
    if (!p) return;

    Object.assign(p, {name, category, image, variants});
    notify("Product updated! Customer site refreshed.");
  } else {
    products.unshift({
      id: Date.now().toString(),
      name, category, image, variants, emoji:"🛒",
      createdAt: new Date().toISOString()
    });
    notify("Product added! It is now live on the customer site.");
  }

  resetForm();
  save();
};

// EDIT
function editProduct(id) {
  const p = products.find(x => String(x.id) === String(id));
  if (!p) return;

  go("products");
  $("editId").value = p.id;
  $("name").value = p.name;
  $("category").value = p.category;
  $("image").value = p.image && !p.image.startsWith("data:image/") ? p.image : "";
  selectedImage = p.image && p.image.startsWith("data:image/") ? p.image : "";
  $("imageFile").value="";
  $("imagePreview").innerHTML = selectedImage ? `<img src="${selectedImage}" alt="Product image"><button type="button" id="clearImage">Remove image</button>` : "";
  $("formTitle").textContent = "Edit product";
  $("saveBtn").textContent = "Update product";

  $("variants").replaceChildren();
  p.variants.forEach(v => addVariant(v));

  $("formPanel").scrollIntoView({behavior:"smooth"});
}

// DELETE
function deleteProduct(id) {
  const p = products.find(x => String(x.id) === String(id));
  if (!p || !confirm("Delete " + p.name + "?")) return;

  products = products.filter(x => String(x.id) !== String(id));
  save();
  notify("Product deleted.");
}

// STOCK STATUS
function status(stock) {
  if (stock <= 0) return ["Out of stock","out"];
  if (stock <= 5) return ["Low stock","low"];
  return ["In stock","in"];
}

function imageHTML(p) {
  if (p.image) {
    return `<img src="${safe(p.image)}" alt="${safe(p.name)}"
      onerror="this.replaceWith(Object.assign(document.createElement('div'),{className:'placeholder',textContent:'🛒'}))">`;
  }
  return `<div class="placeholder">🛒</div>`;
}

function productHTML(p) {
  const summary = p.variants.map(v =>
    `${safe(v.size)}: ${money(v.price)} · ${v.stock} units`
  ).join("<br>");

  return `
    <div class="item">
      ${imageHTML(p)}
      <div class="item-info">
        <b>${safe(p.name)}</b>
        <small>${safe(p.category)}</small>
        <small>${summary}</small>
      </div>
      <div class="item-actions">
        <button class="small-btn" onclick="editProduct('${safe(p.id)}')">Edit</button>
        <button class="small-btn delete"
          onclick="deleteProduct('${safe(p.id)}')">×</button>
      </div>
    </div>`;
}

// OVERVIEW
function renderDashboard() {
  const variants = products.flatMap(p => p.variants || []);
  const low = variants.filter(v => v.stock > 0 && v.stock <= 5);
  const out = variants.filter(v => v.stock <= 0);
  const offers = variants.filter(v =>
    v.offerPrice > 0 && v.offerPrice < v.price
  );

  $("total").textContent = products.length;
  $("low").textContent = low.length;
  $("out").textContent = out.length;
  $("offersCount").textContent = offers.length;

  const alerts = products.flatMap(p =>
    p.variants.filter(v => v.stock <= 5).map(v => `
      <div class="item">
        <div class="item-info">
          <b>${safe(p.name)} · ${safe(v.size)}</b>
          <small>${v.stock} units remaining</small>
        </div>
        <span class="stock-tag ${status(v.stock)[1]}">
          ${status(v.stock)[0]}
        </span>
      </div>
    `)
  );

  $("alerts").innerHTML = alerts.length
    ? alerts.join("")
    : '<div class="empty">All products have healthy stock.</div>';

  $("recent").innerHTML = products.length
    ? products.slice(0, 5).map(productHTML).join("")
    : '<div class="empty">No products added yet.</div>';
}

// PRODUCTS
function renderProducts() {
  const q = $("search").value.toLowerCase().trim();
  const filtered = products.filter(p =>
    p.name.toLowerCase().includes(q) ||
    p.category.toLowerCase().includes(q)
  );

  $("productCount").textContent = products.length + " products";
  $("productList").innerHTML = filtered.length
    ? filtered.map(productHTML).join("")
    : '<div class="empty">No products found.</div>';
}

// INVENTORY
function renderInventory() {
  let units = 0;
  let rows = [];

  products.forEach(p => {
    p.variants.forEach((v, index) => {
      units += Number(v.stock);
      const [label, cls] = status(v.stock);

      rows.push(`
        <div class="item">
          <div class="item-info">
            <b>${safe(p.name)} · ${safe(v.size)}</b>
            <small>${money(v.price)} · ${v.stock} units</small>
          </div>
          <span class="stock-tag ${cls}">${label}</span>
          <div class="item-actions">
            <button class="small-btn"
              onclick="changeStock('${safe(p.id)}',${index},-1)">−</button>
            <button class="small-btn"
              onclick="changeStock('${safe(p.id)}',${index},1)">+</button>
          </div>
        </div>
      `);
    });
  });

  $("units").textContent = units;
  $("alertsCount").textContent =
    products.reduce((n,p) => n + p.variants.filter(v => v.stock <= 5).length, 0);

  $("inventoryList").innerHTML = rows.length
    ? rows.join("")
    : '<div class="empty">No inventory yet.</div>';
}

// CHANGE STOCK
function changeStock(id, index, amount) {
  const p = products.find(x => String(x.id) === String(id));
  if (!p || !p.variants[index]) return;

  const v = p.variants[index];
  if (v.stock + amount < 0) return;

  v.stock += amount;
  save();
}

// OFFERS
function renderOffers() {
  const rows = [];

  products.forEach(p => {
    p.variants.forEach(v => {
      if (v.offerPrice > 0 && v.offerPrice < v.price) {
        const discount = Math.round(
          (1 - v.offerPrice / v.price) * 100
        );

        rows.push(`
          <div class="item">
            ${imageHTML(p)}
            <div class="item-info">
              <b>${safe(p.name)} · ${safe(v.size)}</b>
              <small><s>${money(v.price)}</s>
                <span class="offer-price">${money(v.offerPrice)}</span>
              </small>
              <small>${discount}% discount</small>
            </div>
            <button class="small-btn"
              onclick="editProduct('${safe(p.id)}')">Edit</button>
          </div>
        `);
      }
    });
  });

  $("offerList").innerHTML = rows.length
    ? rows.join("")
    : '<div class="empty">No active offers. Add an offer price to a product size.</div>';
}

// SEARCH
$("search").addEventListener("input", renderProducts);

// LIVE ORDERS — read from the same storage the customer site writes to
let orders = [], orderFilter = "all", knownOrderIds = null;
function loadOrders(){
  try { const o = JSON.parse(localStorage.getItem(ORDER_KEY)); orders = Array.isArray(o) ? o : []; }
  catch(e){ orders = []; }
}
function saveOrders(){
  try { localStorage.setItem(ORDER_KEY, JSON.stringify(orders)); } catch(e){ notify("Could not save orders."); }
}
function fmtDate(iso){
  const d = new Date(iso);
  if (isNaN(d)) return "";
  return d.toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric"}) + " · " +
         d.toLocaleTimeString("en-IN",{hour:"2-digit",minute:"2-digit",hour12:true});
}
function orderHTML(o){
  const isNew = o.status !== "Delivered";
  const wa = String(o.phone||"").replace(/\D/g,"");
  return `
  <div class="order ${isNew?"is-new":"is-done"}">
    <div class="order-top">
      <div><b>${safe(o.id)}</b><small>🕒 ${safe(fmtDate(o.createdAt))}</small></div>
      <span class="ord-status ${isNew?"":"done"}">${isNew?"NEW":"DELIVERED"}</span>
    </div>
    <div class="order-cust">
      <div><span>Name</span><b>${safe(o.name)}</b></div>
      <div><span>Phone</span><b>${safe(o.phone)}</b></div>
      <div><span>Address</span><b>${safe(o.address).replace(/\n/g,"<br>")}</b></div>
    </div>
    <div class="order-items">
      ${(o.items||[]).map(i=>`<div><span>${safe(i.name)} (${safe(i.size)}) × ${Number(i.qty)}</span><span>${money(i.sub)}</span></div>`).join("")}
      <div class="order-total"><span>Total</span><span>${money(o.total)}</span></div>
    </div>
    <div class="order-actions">
      ${isNew
        ? `<button class="small-btn" onclick="setOrderStatus('${safe(o.id)}','Delivered')">✓ Mark delivered</button>`
        : `<button class="small-btn" onclick="setOrderStatus('${safe(o.id)}','New')">↩ Mark as new</button>`}
      <a class="small-btn" href="tel:${safe(wa)}">📞 Call</a>
      <button class="small-btn delete" onclick="deleteOrder('${safe(o.id)}')">Delete</button>
    </div>
  </div>`;
}
function renderOrders(){
  loadOrders();
  const nNew = orders.filter(o=>o.status!=="Delivered").length;
  const done = orders.filter(o=>o.status==="Delivered");
  $("ordNew").textContent = nNew;
  $("ordDone").textContent = done.length;
  $("ordTotal").textContent = orders.length;
  $("ordSales").textContent = money(done.reduce((s,o)=>s+Number(o.total||0),0));
  const badge = $("navBadge"); badge.textContent = nNew; badge.hidden = !nNew;
  document.title = (nNew ? "(" + nNew + ") " : "") + "ANUGRAHA | Admin";
  const q = $("orderSearch").value.toLowerCase().trim();
  const list = orders.filter(o =>
    (orderFilter==="all" || (orderFilter==="Delivered" ? o.status==="Delivered" : o.status!=="Delivered")) &&
    (!q || [o.name,o.phone,o.id].some(v=>String(v||"").toLowerCase().includes(q))));
  $("orderList").innerHTML = list.length ? list.map(orderHTML).join("")
    : '<div class="empty">No orders yet. New customer orders will appear here instantly.</div>';
}
function setOrderStatus(id,status){
  loadOrders();
  const o = orders.find(x=>x.id===id); if(!o) return;
  o.status = status; saveOrders(); renderOrders();
}
function deleteOrder(id){
  if(!confirm("Delete order " + id + "?")) return;
  loadOrders(); orders = orders.filter(x=>x.id!==id); saveOrders(); renderOrders();
}
// Notify when a new order arrives (from the customer site in another tab/window)
function checkNewOrders(){
  loadOrders();
  const ids = new Set(orders.map(o=>o.id));
  if (knownOrderIds){
    const fresh = orders.filter(o=>!knownOrderIds.has(o.id));
    if (fresh.length){ notify("🔔 New order from " + fresh[0].name + " (" + money(fresh[0].total) + ")"); }
  }
  knownOrderIds = ids;
  renderOrders();
}
window.addEventListener("storage", e => { if (e.key===ORDER_KEY) checkNewOrders(); });
setInterval(checkNewOrders, 4000); // fallback refresh
$("orderSearch").addEventListener("input", renderOrders);
document.querySelectorAll("[data-of]").forEach(b=>b.onclick=()=>{
  orderFilter = b.dataset.of;
  document.querySelectorAll("[data-of]").forEach(x=>x.classList.toggle("active",x===b));
  renderOrders();
});

// RENDER ALL
function renderCategories() {
  const base=["Vegetables","Fruits","Ice Cream","Grocery","Beverages"];
  const all=[...new Set([...base,...products.map(p=>p.category).filter(Boolean)])];
  $("categoryList").innerHTML=all.map(c=>`<option value="${safe(c)}">`).join("");
}

function renderAll() {
  renderCategories();
  renderDashboard();
  renderProducts();
  renderInventory();
  renderOffers();
}

resetForm();
renderAll();
checkNewOrders();
